<?php
$error=null;$edit=null;$isAdmin=has_role('Admin');
if(request_method('POST')){require_roles('Admin');try{verify_csrf();$action=post_string('action');if(in_array($action,['create','update'],true)){$name=post_string('full_name');$email=strtolower(post_string('email'));$username=strtolower(post_string('username'));$dept=(int)($_POST['department_id']??0);$specialization=post_string('specialization');$qualification=post_string('qualification');$fee=(float)($_POST['consultation_fee']??0);$avg=max(5,(int)($_POST['average_consultation_minutes']??15));$room=post_string('room_number');$status=post_string('status','Active');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$dept<1||$specialization==='')throw new RuntimeException('Complete all required doctor fields.');if(!preg_match('/^[a-zA-Z0-9._-]{3,80}$/',$username))throw new RuntimeException('Username must be 3–80 characters using letters, numbers, dots, underscores or hyphens.');if($fee<0)throw new RuntimeException('Consultation fee cannot be negative.');if(!in_array($status,['Active','Inactive'],true))throw new RuntimeException('Invalid doctor status.');if((int)query_value("SELECT COUNT(*) FROM departments WHERE department_id=? AND status='Active'",[$dept])===0)throw new RuntimeException('Select an active department.');$pdo=db();$pdo->beginTransaction();if($action==='create'){$password=(string)($_POST['password']??'');if(strlen($password)<8)throw new RuntimeException('New doctor password must contain at least 8 characters.');$role=(int)query_value("SELECT role_id FROM roles WHERE role_name='Doctor'");$stmt=$pdo->prepare("INSERT INTO users (role_id,full_name,username,email,password_hash,phone,account_status) VALUES (?,?,?,?,?,?,?)");$stmt->execute([$role,$name,$username,$email,password_hash($password,PASSWORD_DEFAULT),nullable(post_string('phone')),$status]);$userId=(int)$pdo->lastInsertId();$stmt=$pdo->prepare('INSERT INTO doctors (user_id,department_id,specialization,qualification,consultation_fee,average_consultation_minutes,room_number,status) VALUES (?,?,?,?,?,?,?,?)');$stmt->execute([$userId,$dept,$specialization,nullable($qualification),$fee,$avg,nullable($room),$status]);$id=(int)$pdo->lastInsertId();$code=code_from_id('DOC',$id);$pdo->prepare('UPDATE doctors SET doctor_code=? WHERE doctor_id=?')->execute([$code,$id]);log_action('CREATE','doctors',$id,null,['doctor_code'=>$code]);}else{$id=(int)($_POST['doctor_id']??0);$stmt=$pdo->prepare('SELECT user_id FROM doctors WHERE doctor_id=?');$stmt->execute([$id]);$userId=(int)$stmt->fetchColumn();if($userId<1)throw new RuntimeException('Doctor record not found.');$pdo->prepare('UPDATE users SET full_name=?,email=?,username=?,phone=?,account_status=? WHERE user_id=?')->execute([$name,$email,$username,nullable(post_string('phone')),$status,$userId]);$pdo->prepare('UPDATE doctors SET department_id=?,specialization=?,qualification=?,consultation_fee=?,average_consultation_minutes=?,room_number=?,status=? WHERE doctor_id=?')->execute([$dept,$specialization,nullable($qualification),$fee,$avg,nullable($room),$status,$id]);if(!empty($_POST['password'])){if(strlen((string)$_POST['password'])<8)throw new RuntimeException('Password must contain at least 8 characters.');$pdo->prepare('UPDATE users SET password_hash=? WHERE user_id=?')->execute([password_hash((string)$_POST['password'],PASSWORD_DEFAULT),$userId]);}log_action('UPDATE','doctors',$id);} $pdo->commit();flash('doctor','Doctor saved successfully.','success');redirect_to('doctors');}}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
if(isset($_GET['edit'])&&$isAdmin){$stmt=db()->prepare('SELECT d.*,u.full_name,u.email,u.username,u.phone FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE d.doctor_id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
$departments=db()->query("SELECT * FROM departments WHERE status='Active' ORDER BY department_name")->fetchAll();$rows=db()->query("SELECT d.*,u.full_name,u.email,u.phone,dep.department_name,(SELECT COUNT(*) FROM doctor_schedules s WHERE s.doctor_id=d.doctor_id AND s.status='Active') schedule_count FROM doctors d JOIN users u ON u.user_id=d.user_id JOIN departments dep ON dep.department_id=d.department_id ORDER BY u.full_name")->fetchAll();
?>
<div class="page-header"><div><h2>Doctor directory</h2><p>Clinical profiles, fees, departments and availability.</p></div><?php if($isAdmin):?><button class="btn btn-primary" data-modal-open="doctorModal">＋ Add doctor</button><?php endif;?></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="grid grid-3"><?php foreach($rows as $r):?><div class="card"><div style="display:flex;gap:14px;align-items:center"><div class="avatar" style="width:56px;height:56px;font-size:20px"><?=e(strtoupper(substr($r['full_name'],0,1)))?></div><div><h3 class="mb-0"><?=e($r['full_name'])?></h3><div class="text-muted"><?=e($r['specialization'])?></div><span class="badge badge-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></div></div><div class="divider"></div><div class="grid grid-2" style="gap:10px"><div><div class="table-subtitle">Department</div><strong><?=e($r['department_name'])?></strong></div><div><div class="table-subtitle">Fee</div><strong><?=money($r['consultation_fee'])?></strong></div><div><div class="table-subtitle">Room</div><strong><?=e($r['room_number']??'—')?></strong></div><div><div class="table-subtitle">Schedules</div><strong><?=e($r['schedule_count'])?></strong></div></div><?php if($isAdmin):?><div class="divider"></div><div class="actions"><a class="btn btn-light btn-sm" href="<?=e(route_url('doctors',['edit'=>$r['doctor_id']]))?>">Edit</a><a class="btn btn-light btn-sm" href="<?=e(route_url('schedules',['doctor_id'=>$r['doctor_id']]))?>">Schedule</a></div><?php endif;?></div><?php endforeach;?></div>
<?php if(!$rows):?><div class="card empty-state"><div class="empty-icon">⚕</div><p>No doctors have been configured.</p></div><?php endif;?>
<?php if($isAdmin):?><div class="modal-backdrop <?=($edit||isset($_GET['new']))?'open':''?>" id="doctorModal"><div class="modal"><div class="modal-header"><h3><?=$edit?'Edit doctor':'Add doctor'?></h3><button class="close-btn" data-modal-close>×</button></div><form method="post"><div class="modal-body"><?=csrf_field()?><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="doctor_id" value="<?=$edit['doctor_id']?>"><?php endif;?><div class="form-grid"><div class="field"><label class="required">Full name</label><input class="input" name="full_name" value="<?=e($edit['full_name']??'')?>" required></div><div class="field"><label class="required">Department</label><select class="select" name="department_id" required><option value="">Select</option><?php foreach($departments as $d):?><option value="<?=$d['department_id']?>" <?=($edit['department_id']??'')==$d['department_id']?'selected':''?>><?=e($d['department_name'])?></option><?php endforeach;?></select></div><div class="field"><label class="required">Specialization</label><input class="input" name="specialization" value="<?=e($edit['specialization']??'')?>" required></div><div class="field"><label>Qualification</label><input class="input" name="qualification" value="<?=e($edit['qualification']??'')?>"></div><div class="field"><label class="required">Email</label><input class="input" type="email" name="email" value="<?=e($edit['email']??'')?>" required></div><div class="field"><label class="required">Username</label><input class="input" name="username" value="<?=e($edit['username']??'')?>" required></div><div class="field"><label>Phone</label><input class="input" name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="field"><label><?=$edit?'New password (optional)':'Password'?></label><input class="input" type="password" name="password" <?=$edit?'':'required minlength="8"'?>></div><div class="field"><label>Consultation fee</label><input class="input" type="number" min="0" step="0.01" name="consultation_fee" value="<?=e($edit['consultation_fee']??'0')?>"></div><div class="field"><label>Average minutes</label><input class="input" type="number" min="5" name="average_consultation_minutes" value="<?=e($edit['average_consultation_minutes']??'15')?>"></div><div class="field"><label>Room</label><input class="input" name="room_number" value="<?=e($edit['room_number']??'')?>"></div><div class="field"><label>Status</label><select class="select" name="status"><?php foreach(['Active','Inactive'] as $s):?><option <?=($edit['status']??'Active')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div></div></div><div class="modal-footer"><a class="btn btn-light" href="<?=e(route_url('doctors'))?>">Cancel</a><button class="btn btn-primary">Save doctor</button></div></form></div></div><?php endif;?>
